/**
 * أيقونات Lucide الفعلية المستخدمة في الويب (lucide-react 0.546) محوّلة آلياً إلى ImageVector — نفس
 * المسارات بالضبط (24x24، خط 2، أطراف مستديرة) فتتطابق الأيقونات مع الموقع 1:1. مولَّد آلياً: لا يُعدَّل يدوياً.
 */
private fun lucide(name: String, vararg paths: String): ImageVector {
    val b = ImageVector.Builder(
        name = name, defaultWidth = 24.dp, defaultHeight = 24.dp, viewportWidth = 24f, viewportHeight = 24f
    )
    for (p in paths) {
        b.addPath(
            pathData = PathParser().parsePathString(p).toNodes(),
            fill = null,
            stroke = SolidColor(Color.Black),
            strokeLineWidth = 2f,
            strokeLineCap = StrokeCap.Round,
            strokeLineJoin = StrokeJoin.Round
        )
    }
    return b.build()
}

